package com.pridesys.ticketing.attachment.service;
import com.pridesys.ticketing.dto.*; import com.pridesys.ticketing.entity.*; import com.pridesys.ticketing.repository.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.util.*;
@Service public class AttachmentService { private static final long MAX=10*1024*1024; private static final Set<String> TYPES=Set.of("image/png","image/jpeg","application/pdf","text/plain","application/zip"); private final IssueAttachmentRepository attachments; private final IssueRepository issues; private final ProjectRepository projects; private final FileStorage storage; public AttachmentService(IssueAttachmentRepository a,IssueRepository i,ProjectRepository p,FileStorage s){attachments=a;issues=i;projects=p;storage=s;} public PageResponse<AttachmentResponseDto> list(UserEntity a,long issue,int page,int size){target(a,issue);var p=org.springframework.data.domain.PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100));return PageResponse.of(attachments.findByIssueIdOrderByCreatedAtAsc(issue,p).map(this::map));} public AttachmentResponseDto upload(UserEntity a,long issue,MultipartFile file)throws IOException{target(a,issue);if(file.isEmpty()||file.getSize()>MAX||!TYPES.contains(file.getContentType()))throw new IllegalArgumentException("Attachment rejected");String key=storage.store(file);return map(attachments.save(new IssueAttachmentEntity(issue,a.getId(),Objects.requireNonNullElse(file.getOriginalFilename(),"file"),key,file.getContentType(),file.getSize())));} public InputStream download(UserEntity a,long id)throws IOException{var x=attachments.findById(id).orElseThrow();target(a,x.getIssueId());return storage.load(x.getStorageKey());} public void delete(UserEntity a,long id)throws IOException{var x=attachments.findById(id).orElseThrow();if(x.getUploaderId()!=a.getId()&&a.getRole()!=UserRole.APP_ADMIN)throw new AccessDeniedException("Attachment delete denied");attachments.delete(x);storage.delete(x.getStorageKey());} private IssueEntity target(UserEntity a,long id){var i=issues.findById(id).orElseThrow();if(a.getRole()!=UserRole.APP_ADMIN&&!projects.member(i.getProjectId(),a.getId()))throw new AccessDeniedException("Issue access denied");return i;} private AttachmentResponseDto map(IssueAttachmentEntity x){return new AttachmentResponseDto(x.getId(),x.getIssueId(),x.getUploaderId(),x.getOriginalName(),x.getContentType(),x.getSizeBytes(),x.getCreatedAt());} }
